<script setup lang="ts">
import { computed, onMounted, ref } from 'vue';
import { useRoute, useRouter } from 'vue-router';
import { Users, GraduationCap, CalendarCheck, FileText, Megaphone, Network, ChartColumn, FolderOpen, Plus, Search, ArrowRight, X, Download, LoaderCircle, BookOpen, Check, Clock, Layers, TrendingUp, RefreshCw, Copy, Pencil } from '@lucide/vue';
import { teaching, teachingDownload } from '../teachingApi';
const route = useRoute(); const router = useRouter();
const classes = ref<any[]>([]), workspace = ref<any>(null), metrics = ref<any>({}), teachers = ref<any[]>([]);
const selectedId = ref(''), tab = ref('home'), error = ref(''), message = ref(''), loading = ref(false), busy = ref(false);
const q = ref(''), major = ref(''), grade = ref(''), semester = ref(''), status = ref('active'), page = ref(1), total = ref(0);
const days = ref(30), start = ref(''), end = ref(''), attendanceDate = ref(today()), studentQ = ref(''), resourceQ = ref('');
const modal = ref(''), form = ref<any>({}), importPreview = ref<any>(null), groups = ref<any[]>([]), groupCount = ref(2), replaceGroups = ref(false);
const allLogs = ref<any[]>([]), logPage = ref(1), logTotal = ref(0), studentArchive = ref<any>(null);
let requestId = 0, listRequest = 0;
const shortcuts = [
  {id:'students',name:'学生管理',icon:Users}, {id:'attendance',name:'考勤管理',icon:CalendarCheck},
  {id:'assignments',name:'作业与测试',icon:FileText}, {id:'announcements',name:'公告通知',icon:Megaphone},
  {id:'groups',name:'分组管理',icon:Network}, {id:'analytics',name:'学情分析',icon:ChartColumn}, {id:'resources',name:'班级资料',icon:FolderOpen}
];
const current = computed(() => workspace.value?.classroom);
const readonly = computed(() => !!current.value?.archived);
const students = computed<any[]>(() => (workspace.value?.students || []).filter((s: any) => `${s.student_name} ${s.student_account}`.toLowerCase().includes(studentQ.value.toLowerCase())));
const resources = computed<any[]>(() => (workspace.value?.resources || []).filter((s: any) => `${s.name} ${s.category}`.toLowerCase().includes(resourceQ.value.toLowerCase())));
const todos = computed<any[]>(() => workspace.value?.todos || []);
const overview = computed(() => workspace.value?.overview);
const trend = computed<any[]>(() => workspace.value?.analytics?.trend || []);
const linePoints = computed(() => trend.value.map((p, i) => `${20+i*560/Math.max(1,trend.value.length-1)},${130-(p.rate || 0)*1.1}`).join(' '));
const donut = computed(() => {
  const o = overview.value; if (!o?.total) return {};
  const p = (o.present+o.late)/o.total*100, l=o.leave/o.total*100;
  return {background:`conic-gradient(#155eef 0 ${p}%,#8bb8ff ${p}% ${p+l}%,#a78bfa ${p+l}% 100%)`};
});
const statCards = computed(() => [
  {label:'班级总数',value:metrics.value.classes ?? '—',icon:Users}, {label:'在籍学生',value:metrics.value.students ?? '—',icon:GraduationCap},
  {label:'本月考勤率',value:percent(metrics.value.attendance_rate),icon:CalendarCheck}, {label:'作业完成率',value:percent(metrics.value.assignment_rate),icon:Layers},
  {label:'平均学习进度',value:percent(metrics.value.progress),icon:TrendingUp}
]);
function today() { const d=new Date(); return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`; }
function percent(v: number | null | undefined) { return v == null ? '暂无数据' : `${v}%`; }
function time(v?: string) { return v ? new Date(v).toLocaleString('zh-CN',{hour12:false}) : '无截止时间'; }
function iso(v: string) { return v ? new Date(v).toISOString() : null; }
function overdue(t: any) { return !t.done && t.due_at && new Date(t.due_at).getTime()<Date.now(); }
function studentName(id: string) { return workspace.value?.students.find((s: any)=>s.student_id===id)?.student_name || id; }
function path(suffix='') { return `/classes/${encodeURIComponent(selectedId.value)}${suffix}`; }
async function loadClasses(preferred=selectedId.value) {
  const serial=++listRequest; loading.value=true; error.value='';
  try {
    const params=new URLSearchParams({q:q.value,major:major.value,grade:grade.value,semester:semester.value,status:status.value,page:String(page.value),size:'50'});
    const [list,stats]=await Promise.all([teaching('/classes?'+params),teaching('/metrics')]);
    if (serial!==listRequest) return;
    classes.value=list.items; total.value=list.total; metrics.value=stats;
    const id=list.items.find((c: any)=>c.id===preferred)?.id || list.items[0]?.id || '';
    if (id) await selectClass(id); else { ++requestId; selectedId.value=''; workspace.value=null; }
  } catch(e) { if(serial===listRequest) error.value=String((e as Error).message); }
  finally { if(serial===listRequest) loading.value=false; }
}
async function selectClass(id: string) {
  const serial=++requestId; selectedId.value=id; workspace.value=null; loading.value=true; error.value=''; importPreview.value=null; modal.value='';
  await router.replace({query:{...route.query,class:id}});
  try {
    const params=new URLSearchParams({days:String(days.value),attendance_date:attendanceDate.value});
    if(start.value) params.set('start',start.value); if(end.value) params.set('end',end.value);
    const data=await teaching(`/classes/${encodeURIComponent(id)}/workspace?${params}`);
    if(serial===requestId) { workspace.value=data; groups.value=JSON.parse(JSON.stringify(data.groups)); replaceGroups.value=false; }
  } catch(e) { if(serial===requestId) error.value=(e as Error).message; }
  finally { if(serial===requestId) loading.value=false; }
}
async function refresh() { await loadClasses(); }
async function act(action: ()=>Promise<unknown>, success='操作成功，已保存') {
  if(busy.value) return; busy.value=true; error.value=''; message.value='';
  try { await action(); message.value=success; await refresh(); }
  catch(e) { error.value=(e as Error).message; }
  finally { busy.value=false; }
}
function open(kind: string, data?: any) {
  error.value=''; modal.value=kind;
  if(kind==='class') form.value=data ? {...data} : {name:'',major:'',grade:'',semester:'',description:'',teacher_id:teachers.value[0]?.id || ''};
  else if(kind==='attendance') form.value=data ? {...data,records:data.records.map((r: any)=>({...r,status:r.status || 'present'}))} : {title:'课堂考勤',attendance_date:today(),completed:true,records:(workspace.value?.students || []).map((s: any)=>({...s,status:'present'}))};
  else if(kind==='assignment') form.value=data ? {...data,due_at:new Date(new Date(data.due_at).getTime()-new Date().getTimezoneOffset()*60000).toISOString().slice(0,16)} : {title:'',content:'',kind:'assignment',status:'draft',due_at:''};
  else if(kind==='announcement') form.value=data ? {...data,pinned:!!data.pinned} : {title:'',content:'',status:'draft',pinned:false};
  else if(kind==='todo') form.value={title:'',due_at:'',priority:1,done:false};
  else form.value=data ? {...data} : {};
}
async function save() {
  const f=form.value, cid=selectedId.value;
  await act(async()=>{
    if(modal.value==='class') {
      const result=await teaching(`/classes${f.id?'/'+f.id:''}`,f.id?'PUT':'POST',{name:f.name,major:f.major,grade:f.grade,semester:f.semester,description:f.description,teacher_id:f.teacher_id}); selectedId.value=result.id; if(!f.id){status.value='active';page.value=1;q.value='';major.value='';grade.value='';semester.value='';}
    } else if(modal.value==='attendance') await teaching(`/classes/${cid}/attendance${f.id?'/'+f.id:''}`,f.id?'PUT':'POST',{title:f.title,attendance_date:f.attendance_date,completed:f.completed,records:f.records.map((r: any)=>({student_id:r.student_id,status:r.status}))});
    else if(modal.value==='assignment') await teaching(`/classes/${cid}/assignments${f.id?'/'+f.id:''}`,f.id?'PUT':'POST',{title:f.title,content:f.content,kind:f.kind,status:f.status,due_at:iso(f.due_at)});
    else if(modal.value==='announcement') await teaching(`/classes/${cid}/announcements${f.id?'/'+f.id:''}`,f.id?'PUT':'POST',{title:f.title,content:f.content,status:f.status,pinned:f.pinned});
    else if(modal.value==='todo') await teaching(`/classes/${cid}/todos`,'POST',{...f,due_at:iso(f.due_at)});
    else if(modal.value==='grade') await teaching(`/classes/${cid}/assignments/${f.assignment_id}/grades/${f.student_id}`,'PUT',{score:Number(f.score),feedback:f.feedback || ''});
    else if(modal.value==='archive') await teaching(`/classes/${cid}/archive`,'POST');
    else if(modal.value==='remove') await teaching(`/classes/${cid}/students/${f.student_id}`,'DELETE');
    else if(modal.value==='delete-resource') await teaching(`/classes/${cid}/resources/${f.id}`,'DELETE');
    modal.value='';
  });
}
async function download(suffix: string,name: string) { try { await teachingDownload(suffix,name); } catch(e) { error.value=(e as Error).message; } }
async function importFile(event: Event) {
  const file=(event.target as HTMLInputElement).files?.[0]; if(!file) return;
  const cid=selectedId.value; busy.value=true; error.value='';
  try { const p=await teaching(`/classes/${cid}/students/import-preview?filename=${encodeURIComponent(file.name)}`,'POST',file); if(cid===selectedId.value) importPreview.value=p; }
  catch(e) {error.value=(e as Error).message;} finally {busy.value=false;(event.target as HTMLInputElement).value='';}
}
async function upload(event: Event) {
  const file=(event.target as HTMLInputElement).files?.[0]; if(!file) return;
  await act(()=>teaching(path(`/resources?filename=${encodeURIComponent(file.name)}&category=${encodeURIComponent(form.value.category || '课件')}&visible=${!!form.value.visible}`),'POST',file),'资料已上传');
  (event.target as HTMLInputElement).value='';
}
async function randomGroups() {
  error.value=''; busy.value=true;
  try { const result=await teaching(path(`/groups/preview?count=${groupCount.value}`),'POST'); groups.value=result.groups; replaceGroups.value=false; message.value='随机分组仅为预览，确认后才会保存'; }
  catch(e){error.value=(e as Error).message;} finally{busy.value=false;}
}
async function viewArchive(sid: string) { try { studentArchive.value=await teaching(path(`/students/${sid}/archive`)); modal.value='student-archive'; } catch(e){error.value=(e as Error).message;} }
async function logs() { try {const result=await teaching(path(`/logs?page=${logPage.value}`));allLogs.value=result.items;logTotal.value=result.total;tab.value='logs';}catch(e){error.value=(e as Error).message;} }
async function copyCode() { try { await navigator.clipboard.writeText(current.value.code);message.value='邀请码已复制';} catch {error.value='复制失败，请手动复制邀请码';} }
onMounted(async()=>{
  await loadClasses(String(route.query.class || ''));
  try { teachers.value=(await teaching('/teachers')).items; } catch(e){error.value=(e as Error).message;}
});
</script>

<template>
  <div class="class-upgrade">
    <section class="cm-hero"><div><span>教师工作台 › 班级管理</span><h1>班级管理</h1><p>高效管理教学班级，掌握学生学习动态，支持教学组织、过程管理与学情分析。</p></div><button class="primary" @click="open('class')"><Plus :size="17"/>创建班级</button></section>
    <div v-if="error" role="alert" class="cm-alert error">{{ error }}<button @click="refresh"><RefreshCw :size="15"/>重试</button></div>
    <div v-if="message" role="status" class="cm-alert success">{{ message }}<button aria-label="关闭提示" @click="message=''"><X :size="16"/></button></div>
    <section class="cm-metrics"><article v-for="s in statCards" :key="s.label"><i><component :is="s.icon" :size="25"/></i><div><small>{{ s.label }}</small><strong :class="{'no-data':s.value==='暂无数据'}">{{ s.value }}</strong></div></article></section>
    <details class="cm-rules"><summary>统计口径与数据来源</summary><p>仅统计未归档班级。在籍学生跨班去重；本月已完成考勤中，迟到计入出勤、请假从应考勤人次扣除；作业完成率仅包含已截止的已发布作业，名单在发布时固定；学习进度按已完成学习任务 / 已分配任务计算。无分母时显示暂无数据。活跃度为在籍学生中当天完成定位练习、测验或提交作业/任务的去重人数占比，不包含入班前记录。</p></details>
    <div class="cm-layout">
      <aside class="cm-panel cm-list"><header><h2>班级列表 <small>{{total}}</small></h2><button @click="open('class')" aria-label="创建班级"><Plus :size="18"/></button></header>
        <form class="cm-filters" @submit.prevent="page=1;loadClasses()"><label class="cm-search"><Search :size="16"/><input v-model="q" placeholder="搜索班级名称"/></label><div><input v-model="major" placeholder="专业" aria-label="专业筛选"/><input v-model="grade" placeholder="年级" aria-label="年级筛选"/></div><input v-model="semester" placeholder="学期" aria-label="学期筛选"/><div><select v-model="status" aria-label="班级状态"><option value="active">在用班级</option><option value="archived">归档班级</option><option value="">全部状态</option></select><button type="submit">筛选</button></div></form>
        <p v-if="loading && !classes.length" class="empty">正在加载班级…</p><p v-else-if="!classes.length" class="empty">还没有班级或没有匹配结果。<button @click="open('class')">创建第一个班级</button></p>
        <button v-for="c in classes" :key="c.id" class="cm-class" :class="{active:c.id===selectedId}" :disabled="busy" @click="tab='home';selectClass(c.id)"><GraduationCap :size="22"/><span><strong>{{c.name}}</strong><small>{{c.major || '未设置专业'}} · {{c.grade || '未设置年级'}}</small><small>编号 {{c.id}} · {{c.archived?'已归档':'在用'}}</small></span><b>{{c.student_count}}人</b></button>
        <footer v-if="total>50"><button :disabled="page===1" @click="page--;loadClasses()">上一页</button><span>{{page}}</span><button :disabled="page*50>=total" @click="page++;loadClasses()">下一页</button></footer>
      </aside>
      <div class="cm-main">
        <section class="cm-panel cm-shortcuts"><header><h2>快捷功能</h2><button @click="tab='home'">班级首页</button></header><div><button v-for="s in shortcuts" :key="s.id" :class="{active:tab===s.id}" :disabled="!current" @click="tab=s.id"><component :is="s.icon" :size="25"/><span>{{s.name}}</span></button></div></section>
        <div v-if="loading" class="cm-panel empty"><LoaderCircle class="spin" :size="24"/>正在获取班级数据…</div>
        <div v-else-if="!current" class="cm-panel cm-empty"><GraduationCap :size="42"/><h2>{{selectedId&&error?'班级数据暂不可用':'还没有班级'}}</h2><p>{{selectedId&&error?'请检查上方错误提示后重试。':'创建班级后，即可邀请学生、组织教学并查看真实学情。'}}</p><button v-if="!selectedId" class="primary" @click="open('class')">创建班级</button></div>
        <template v-else>
          <section class="cm-selected"><div><strong>{{current.name}}</strong><small>{{current.semester || '未设置学期'}} · 任课教师 {{current.teacher_name}} <b v-if="readonly"> · 已归档（历史只读）</b></small></div><div><button @click="copyCode"><Copy :size="15"/>邀请码 {{current.code}}</button><button :disabled="readonly" @click="open('class',current)"><Pencil :size="15"/>编辑</button><button :disabled="readonly" @click="open('archive')">归档</button></div></section>
          <div v-if="tab==='home'" class="cm-home-grid">
            <section class="cm-panel"><header><h2>班级概览</h2><button @click="tab='attendance'">查看详情 <ArrowRight :size="15"/></button></header><label class="date-label">考勤日期<input v-model="attendanceDate" type="date" @change="selectClass(selectedId)"/></label><div v-if="overview" class="cm-overview"><div class="donut" :style="donut"><span><strong>{{overview.total}}</strong><small>本次应考勤人数</small></span></div><ul><li v-for="s in [{key:'present',name:'出勤',color:'#155eef'},{key:'late',name:'迟到',color:'#3b82f6'},{key:'leave',name:'请假',color:'#8bb8ff'},{key:'absent',name:'缺勤',color:'#a78bfa'}]" :key="s.key"><i :style="{background:s.color}"/>{{s.name}}<b>{{overview[s.key]}}人</b><small>{{overview.total?Math.round(overview[s.key]/overview.total*100):0}}%</small></li></ul></div><p v-else class="empty">所选日期暂无已完成考勤数据</p><small v-if="overview">{{overview.session_title}} · 仅代表该次考勤，不作为长期学习状态。</small></section>
            <section class="cm-panel"><header><h2>学习活跃度</h2><select v-model="days" aria-label="活跃度日期范围" @change="start='';end='';selectClass(selectedId)"><option :value="7">最近7天</option><option :value="30">最近30天</option><option :value="90">最近90天</option></select></header><svg v-if="workspace.analytics.has_activity" class="cm-line" viewBox="0 0 600 160" role="img" aria-label="班级学习活跃度"><path d="M20 20H580M20 75H580M20 130H580" fill="none" stroke="#e3ebfa"/><polyline :points="linePoints" fill="none" stroke="#155eef" stroke-width="2.5"/><circle v-for="(p,i) in trend" :key="p.date" :cx="20+i*560/Math.max(1,trend.length-1)" :cy="130-(p.rate||0)*1.1" r="3" fill="#fff" stroke="#155eef"><title>{{p.date}}：{{p.active}}人（{{percent(p.rate)}}）</title></circle><text x="20" y="153">{{trend[0]?.date}}</text><text x="485" y="153">{{trend[trend.length-1]?.date}}</text></svg><p v-else class="empty">最近{{days}}天暂无有效学习记录</p><button @click="tab='analytics'">查看学情分析 →</button></section>
            <section class="cm-panel"><header><h2><Clock :size="20"/>近期动态</h2><button @click="logPage=1;logs()">全部 →</button></header><ul class="cm-events"><li v-for="l in workspace.logs" :key="l.id"><span>{{l.description}}<small>{{l.actor_name}}</small></span><time>{{time(l.created_at)}}</time></li></ul><p v-if="!workspace.logs.length" class="empty">暂无教学操作记录</p></section>
            <section class="cm-panel"><header><h2>待办事项 <em>{{todos.filter(t=>!t.done).length}}</em></h2><button @click="tab='todos'">全部 →</button></header><div v-for="t in todos.filter(t=>!t.done).slice(0,4)" :key="t.id" class="cm-todo"><button @click="tab=t.tab">{{t.title}}</button><small :class="{overdue:overdue(t)}">{{overdue(t)?'已逾期 · ':''}}{{time(t.due_at)}}</small></div><p v-if="!todos.some(t=>!t.done)" class="empty">暂无待办事项</p><button :disabled="readonly" @click="open('todo')">＋ 新建待办</button></section>
          </div>
          <section v-if="tab==='students'" class="cm-panel"><header><h2>学生管理</h2><div><button @click="download('/import-template?format=xlsx','学生导入模板.xlsx')">下载模板</button><label class="upload" :class="{disabled:readonly||busy}"><input :disabled="readonly||busy" type="file" accept=".csv,.xlsx" hidden @change="importFile"/>导入 Excel / CSV</label><button @click="download(path('/export/students'),'班级名单.csv')"><Download :size="15"/>导出名单</button></div></header><div v-if="workspace.applications?.length" class="cm-preview"><h3>待处理入班申请</h3><div v-for="a in workspace.applications" :key="a.id" class="cm-todo"><span>{{a.student_name}} · {{a.student_account}}</span><div><button :disabled="busy||readonly" @click="act(()=>teaching(path(`/join-requests/${a.id}/decision`),'POST',{approve:true}))">批准加入</button><button :disabled="busy||readonly" @click="act(()=>teaching(path(`/join-requests/${a.id}/decision`),'POST',{approve:false}))">拒绝</button></div></div></div><p class="hint">仅导入已经注册的有效学生账号；可复制邀请码让学生自行加入。导入前会检查重复和账号姓名。</p><input v-model="studentQ" placeholder="搜索姓名或账号" aria-label="搜索学生"/>
            <div v-if="importPreview" class="cm-preview"><h3>导入预览 · 可导入 {{importPreview.valid}} 人</h3><div class="cm-table-wrap"><table><thead><tr><th>行</th><th>账号</th><th>姓名</th><th>检查结果</th></tr></thead><tbody><tr v-for="r in importPreview.rows" :key="r.row"><td>{{r.row}}</td><td>{{r.account}}</td><td>{{r.name}}</td><td :class="{overdue:r.error}">{{r.error || '可导入'}}</td></tr></tbody></table></div><button class="primary" :disabled="busy||!importPreview.valid||readonly" @click="act(()=>teaching(path('/students/import'),'POST',{token:importPreview.token}),'学生已导入')">确认导入有效行</button><button @click="importPreview=null">取消</button></div>
            <div class="cm-table-wrap"><table><thead><tr><th>姓名</th><th>账号</th><th>加入时间</th><th>操作</th></tr></thead><tbody><tr v-for="s in students" :key="s.student_id"><td>{{s.student_name}}</td><td>{{s.student_account}}</td><td>{{time(s.joined_at)}}</td><td><button @click="viewArchive(s.student_id)">学习档案</button><button :disabled="readonly" @click="open('remove',s)">移出班级</button></td></tr></tbody></table></div><p v-if="!students.length" class="empty">暂无匹配的学生</p><RouterLink to="/teacher/classroom-guidance">进入原有学习建议与 AI 指导工作台 →</RouterLink>
          </section>
          <section v-if="tab==='attendance'" class="cm-panel"><header><h2>考勤管理</h2><div><button :disabled="readonly" @click="open('attendance')">＋ 创建考勤</button><button @click="download(path('/export/attendance'),'考勤报表.csv')">导出报表</button></div></header><label>按日期查询<input v-model="attendanceDate" type="date"/></label><div v-for="a in workspace.attendance.filter((a:any)=>!attendanceDate||a.attendance_date===attendanceDate)" :key="a.id" class="cm-row-card"><header><strong>{{a.title}} · {{a.attendance_date}}</strong><button :disabled="readonly" @click="open('attendance',a)">{{a.completed?'调整登记':'继续登记'}}</button></header><p>{{a.completed?'已完成':'草稿'}} · {{a.teacher_name}} · {{a.records.length}}人</p><details><summary>查看登记明细</summary><p v-for="r in a.records" :key="r.student_id">{{r.student_name}}：{{({present:'出勤',late:'迟到',leave:'请假',absent:'缺勤'} as any)[r.status] || '未登记'}}</p></details></div><p v-if="!workspace.attendance.some((a:any)=>!attendanceDate||a.attendance_date===attendanceDate)" class="empty">该日期暂无考勤活动</p></section>
          <section v-if="tab==='assignments'" class="cm-panel"><header><h2>作业、测试与学习任务</h2><div><button :disabled="readonly" @click="open('assignment')">＋ 创建作业 / 任务</button><button @click="download(path('/export/grades'),'成绩.csv')">导出成绩</button></div></header><p class="hint">发布到当前所选班级。学习任务提交计为完成；作业成绩由教师审核后保存。命题可复用<RouterLink to="/teacher/exam-settings">题型与提示词</RouterLink>，复制已审核的题目到正文。</p><article v-for="a in workspace.assignments" :key="a.id" class="cm-row-card"><header><h3>{{a.title}}</h3><button v-if="a.status==='draft'" :disabled="readonly" @click="open('assignment',a)">编辑 / 发布</button></header><small>{{a.kind==='task'?'学习任务':'作业与测试'}} · {{a.status==='draft'?'草稿':'已发布'}} · 截止 {{time(a.due_at)}}</small><p class="preserve">{{a.content}}</p><details><summary>提交与批改 · {{a.submissions.filter((s:any)=>s.submitted_at).length}} / {{a.submissions.length}} 已交</summary><div class="cm-table-wrap"><table><thead><tr><th>学生</th><th>作答内容</th><th>成绩</th><th>批改</th></tr></thead><tbody><tr v-for="s in a.submissions" :key="s.student_id"><td>{{s.student_name}}<small>{{s.submitted_at?time(s.submitted_at):'未提交'}}</small></td><td class="preserve">{{s.content || '—'}}</td><td>{{s.score ?? '未批改'}}</td><td><button :disabled="readonly||!s.submitted_at" @click="open('grade',{...s,assignment_id:a.id})">教师批改</button></td></tr></tbody></table></div></details></article><p v-if="!workspace.assignments.length" class="empty">尚未创建作业或学习任务</p></section>
          <section v-if="tab==='announcements'" class="cm-panel"><header><h2>公告通知</h2><button :disabled="readonly" @click="open('announcement')">＋ 创建公告</button></header><article v-for="a in workspace.announcements" :key="a.id" class="cm-row-card"><header><h3>{{a.pinned?'📌 ':''}}{{a.title}}</h3><button :disabled="readonly" @click="open('announcement',a)">编辑 / 发布 / 撤回</button></header><small>{{({draft:'草稿',published:'已发布',withdrawn:'已撤回'} as any)[a.status]}} · {{a.teacher_name}} · {{time(a.published_at || a.created_at)}}</small><p class="preserve">{{a.content}}</p></article><p v-if="!workspace.announcements.length" class="empty">暂无公告，发布后学生可在“我的班级”查看。</p></section>
          <section v-if="tab==='groups'" class="cm-panel"><header><h2>学习小组</h2><div><input v-model.number="groupCount" type="number" min="1" max="200" aria-label="随机分组组数"/><button :disabled="busy||readonly" @click="randomGroups">随机分组预览</button><button :disabled="readonly" @click="groups.push({name:'新小组',leader_id:'',members:[]})">＋ 手动建组</button></div></header><p class="hint">预览不会保存。可以调整组员、组长和组名，保存时会校验重复成员。</p><div class="cm-group-grid"><div v-for="(g,i) in groups" :key="i" class="cm-row-card"><header><input v-model="g.name" :disabled="readonly" aria-label="小组名称"/><button :disabled="readonly" @click="groups.splice(i,1)">移除组</button></header><label>组长<select v-model="g.leader_id" :disabled="readonly"><option value="">未设置</option><option v-for="id in g.members" :key="id" :value="id">{{studentName(id)}}</option></select></label><label v-for="s in workspace.students" :key="s.student_id" class="check"><input v-model="g.members" :value="s.student_id" type="checkbox" :disabled="readonly"/>{{s.student_name}}</label></div></div><p v-if="!groups.length" class="empty">暂无学习小组</p><label v-if="workspace.groups.length" class="check"><input v-model="replaceGroups" type="checkbox" :disabled="readonly"/>确认用当前预览替换已有分组</label><button class="primary" :disabled="busy||readonly|| (!!workspace.groups.length&&!replaceGroups)" @click="act(()=>teaching(path('/groups'),'PUT',{groups:groups.map(g=>({name:g.name,leader_id:g.leader_id||'',members:g.members})),replace:replaceGroups}),'分组已保存')">确认保存分组</button></section>
          <section v-if="tab==='analytics'" class="cm-panel"><header><h2>学情分析</h2></header><form class="cm-date-filter" @submit.prevent="selectClass(selectedId)"><label>开始日期<input v-model="start" type="date"/></label><label>结束日期<input v-model="end" type="date"/></label><button type="submit">应用日期范围</button></form><h3>学习任务完成情况</h3><div class="cm-table-wrap"><table><thead><tr><th>学生</th><th>完成 / 分配</th><th>学习进度</th></tr></thead><tbody><tr v-for="s in workspace.analytics.students" :key="s.student_id"><td>{{s.student_name}}</td><td>{{s.completed_tasks}} / {{s.assigned_tasks}}</td><td>{{s.assigned_tasks?percent(Math.round(s.completed_tasks/s.assigned_tasks*100)):'暂无数据'}}</td></tr></tbody></table></div><h3>成绩分布（所选日期内的练习、测验及教师批改成绩）</h3><div class="cm-score-bars"><div v-for="s in workspace.analytics.score_distribution" :key="s.label"><span>{{s.label}}</span><meter min="0" :max="Math.max(1,...workspace.analytics.score_distribution.map((r:any)=>r.count))" :value="s.count"/><b>{{s.count}}次</b></div></div><h3>考勤变化</h3><p v-for="a in workspace.analytics.attendance" :key="a.date">{{a.date}} · 出勤率 {{percent(a.rate)}}</p><p v-if="!workspace.analytics.attendance.length" class="empty">所选范围暂无完成考勤记录</p><h3>已发布作业与任务</h3><p v-for="a in workspace.analytics.assignments" :key="a.id">{{a.title}} · {{a.submitted}} / {{a.expected}} 已提交</p><details><summary>每日学习活跃明细</summary><div class="cm-table-wrap"><table><thead><tr><th>日期</th><th>活跃学生数</th><th>活跃度</th></tr></thead><tbody><tr v-for="p in trend" :key="p.date"><td>{{p.date}}</td><td>{{p.active}}</td><td>{{percent(p.rate)}}</td></tr></tbody></table></div></details></section>
          <section v-if="tab==='resources'" class="cm-panel"><header><h2>班级资料</h2></header><div class="cm-upload-form"><input v-model="form.category" placeholder="资料分类，默认课件" aria-label="资料分类"/><label class="check"><input v-model="form.visible" type="checkbox" :disabled="readonly"/>上传后学生可见</label><label class="upload" :class="{disabled:busy||readonly}"><input type="file" :disabled="busy||readonly" accept=".pdf,.doc,.docx,.ppt,.pptx,.xls,.xlsx,.png,.jpg,.jpeg,.webp" hidden @change="upload"/>＋ 上传资料</label></div><p class="hint">支持 PDF、Word、PPT、Excel 与图片，每份最多 25 MB；默认仅教师可见。</p><input v-model="resourceQ" placeholder="搜索文件名称或分类" aria-label="搜索资料"/><div v-for="r in resources" :key="r.id" class="cm-row-card"><header><strong>{{r.name}}</strong><button @click="download(path(`/resources/${r.id}/download`),r.name)">下载</button></header><p>{{r.category}} · {{(r.size/1024).toFixed(1)}} KB · {{r.visible?'学生可见':'仅教师可见'}}</p><button :disabled="readonly||busy" @click="act(()=>teaching(path(`/resources/${r.id}`),'PATCH',{category:r.category,visible:!r.visible}))">{{r.visible?'设为教师可见':'发布给学生'}}</button><button :disabled="readonly" @click="open('delete-resource',r)">删除</button></div><p v-if="!resources.length" class="empty">暂无匹配资料</p></section>
          <section v-if="tab==='todos'" class="cm-panel"><header><h2>教师待办</h2><button :disabled="readonly" @click="open('todo')">＋ 新建待办</button></header><div v-for="t in todos" :key="t.id" class="cm-todo"><label v-if="t.custom" class="check"><input type="checkbox" :checked="!!t.done" :disabled="readonly||busy" @change="act(()=>teaching(path(`/todos/${t.id}`),'PUT',{title:t.title,due_at:t.due_at,priority:t.priority,done:!t.done}))"/>{{t.title}}</label><button v-else @click="tab=t.tab">{{t.title}} →</button><small :class="{overdue:overdue(t)}">{{t.done?'已完成 · ':overdue(t)?'已逾期 · ':''}}{{time(t.due_at)}}</small></div><p v-if="!todos.length" class="empty">暂无待办事项</p></section>
          <section v-if="tab==='logs'" class="cm-panel"><header><h2>全部教学动态</h2></header><ul class="cm-events"><li v-for="l in allLogs" :key="l.id"><span>{{l.description}}<small>{{l.actor_name}}</small></span><time>{{time(l.created_at)}}</time></li></ul><footer><button :disabled="logPage===1" @click="logPage--;logs()">上一页</button><span>{{logPage}} · {{logTotal}}条</span><button :disabled="logPage*30>=logTotal" @click="logPage++;logs()">下一页</button></footer></section>
        </template>
      </div>
    </div>
    <Teleport to="body"><div v-if="modal" class="cm-overlay" @click.self="!busy&&(modal='')"><section class="cm-dialog" role="dialog" aria-modal="true" :aria-label="({class:'班级信息',attendance:'考勤登记',assignment:'作业与任务',announcement:'公告通知',todo:'新增待办',grade:'教师批改','student-archive':'学生学习档案'} as any)[modal] || '确认操作'"><header><h2>{{({class:'班级信息',attendance:'考勤登记',assignment:'作业与任务',announcement:'公告通知',todo:'新增待办',grade:'教师批改','student-archive':'学生学习档案'} as any)[modal] || '确认操作'}}</h2><button :disabled="busy" aria-label="关闭" @click="modal=''"><X :size="22"/></button></header><p v-if="error" class="cm-alert error" role="alert">{{error}}</p>
      <form v-if="modal!=='student-archive'" @submit.prevent="save">
        <template v-if="modal==='class'"><label>班级名称 *<input v-model="form.name" required minlength="2" maxlength="60"/></label><div class="cm-form-grid"><label>专业<input v-model="form.major" maxlength="80"/></label><label>年级<input v-model="form.grade" maxlength="30"/></label><label>学期<input v-model="form.semester" maxlength="50"/></label><label>任课教师<select v-model="form.teacher_id"><option v-for="t in teachers" :key="t.id" :value="t.id">{{t.name}}</option></select></label></div><label>班级说明<textarea v-model="form.description" maxlength="500" rows="3"/></label></template>
        <template v-else-if="modal==='attendance'"><label>活动名称<input v-model="form.title" required maxlength="120"/></label><label>日期<input v-model="form.attendance_date" type="date" :max="today()" required :disabled="!!form.id"/></label><div><button type="button" @click="form.records.forEach((r:any)=>r.status='present')">全部出勤</button><button type="button" @click="form.records.forEach((r:any)=>r.status='absent')">全部缺勤</button></div><div v-for="r in form.records" :key="r.student_id" class="cm-attendance-row"><span>{{r.student_name}}</span><select v-model="r.status"><option value="present">出勤</option><option value="late">迟到</option><option value="leave">请假</option><option value="absent">缺勤</option></select></div><label class="check"><input v-model="form.completed" type="checkbox"/>完成考勤并计入统计（取消勾选保存为草稿）</label></template>
        <template v-else-if="modal==='assignment'"><label>标题<input v-model="form.title" required maxlength="120"/></label><label>类型<select v-model="form.kind"><option value="assignment">作业与测试（教师批改）</option><option value="task">学习任务（学生提交后计为完成）</option></select></label><label>题目 / 任务要求<textarea v-model="form.content" required rows="7" maxlength="20000"/></label><label>截止时间<input v-model="form.due_at" type="datetime-local" required/></label><label>发布状态<select v-model="form.status"><option value="draft">草稿</option><option value="published">发布给当前班级全部在籍学生</option></select></label></template>
        <template v-else-if="modal==='announcement'"><label>标题<input v-model="form.title" required maxlength="120"/></label><label>正文<textarea v-model="form.content" required rows="7" maxlength="20000"/></label><label>状态<select v-model="form.status"><option value="draft">草稿</option><option value="published">发布到当前班级</option><option value="withdrawn">撤回</option></select></label><label class="check"><input v-model="form.pinned" type="checkbox"/>置顶公告</label></template>
        <template v-else-if="modal==='todo'"><label>待办事项<input v-model="form.title" required maxlength="200"/></label><label>截止时间<input v-model="form.due_at" type="datetime-local"/></label><label>优先级<select v-model.number="form.priority"><option :value="0">低</option><option :value="1">普通</option><option :value="2">重要</option><option :value="3">紧急</option></select></label></template>
        <template v-else-if="modal==='grade'"><p class="preserve">{{form.content}}</p><label>成绩（0–100）<input v-model.number="form.score" type="number" min="0" max="100" step="0.1" required/></label><label>教师评语<textarea v-model="form.feedback" maxlength="2000" rows="4"/></label><p class="hint">此操作保存正式成绩，请核实学生作答。</p></template>
        <p v-else-if="modal==='archive'">确认归档「{{current.name}}」？归档后禁止新增和修改，历史名单、成绩、考勤和资料仍然保留。</p>
        <p v-else-if="modal==='remove'">确认将 {{form.student_name}} 移出班级？历史作答、成绩和考勤会保留，学生将无法继续访问班级资料。</p>
        <p v-else-if="modal==='delete-resource'">确认移除 {{form.name}}？该资料将不再提供下载。</p>
        <footer><button type="button" :disabled="busy" @click="modal=''">取消</button><button class="primary" type="submit" :disabled="busy"><LoaderCircle v-if="busy" class="spin" :size="16"/>{{busy?'正在保存…':'确认保存'}}</button></footer>
      </form>
      <div v-else-if="studentArchive"><h3>{{studentArchive.student_name}} · {{studentArchive.student_account}}</h3><p>总作答 {{studentArchive.total_attempts}} 次 · 平均成绩 {{studentArchive.average_score ?? '暂无数据'}}</p><h3>待巩固知识</h3><p v-for="(w,i) in studentArchive.weak_points" :key="i">{{w}}</p><p v-if="!studentArchive.weak_points?.length">暂无待巩固记录</p><RouterLink to="/teacher/classroom-guidance" @click="modal=''">查看详细作答与学习建议 →</RouterLink></div>
    </section></div></Teleport>
  </div>
</template>

